def tier_claim(claim, evidence):
    ev = evidence.lower()
    if any(k in ev for k in ('manuscript', 'archive', 'exists', 'dated', 'philology')):
        return ('DOCUMENTED', f'primary/artifact evidence: {evidence}')
    if 'historians agree' in ev or 'consensus' in ev:
        return ('SCHOLARLY CONSENSUS', f'cited agreement: {evidence}')
    if 'lineage' in ev or 'origin story' in ev:
        tier = 'CONTESTED' if 'debat' in ev else 'TRADITIONAL'
        return (tier, f'lineage claim, honestly labeled: {evidence}')
    return ('CONTESTED', f'open question: {evidence}')

tests = [
    ('The Corpus Hermeticum manuscripts date to late antiquity', 'Casaubon 1614 philology; manuscript tradition'),
    ('The Golden Dawn was founded by ancient adepts', 'lineage origin story; Cipher MS debate'),
    ('Dee kept angel diaries 1581-1589', 'the diaries exist in archives'),
]
for claim, ev in tests:
    print(tier_claim(claim, ev))
# Lesson: tier each claim separately — the reflex, automated.

stopwords={'the','and','for','was','all','are','that','with','from','his'}
passages = {
    'asclepius': 'god is the glory of all things and the divine is the principle of all that is',
    'poimandres': 'the light was the mind of god and the mind encompassed all things',
    'emerald': 'as above so below and as below so above for the miracle of the one thing',
}
def sig(p):
    return {w.strip('.,;:') for w in p.lower().split() if len(w)>3 and w not in stopwords}
idx={k:sig(v) for k,v in passages.items()}
keys=list(idx)
for i in range(len(keys)):
    for j in range(i+1,len(keys)):
        shared=idx[keys[i]]&idx[keys[j]]
        print(f'{keys[i]} x {keys[j]}: {sorted(shared)}')
# Lesson: shared vocabulary maps the current — concordance before commentary.

pairs=[(0,9),(1,8),(2,7),(3,6),(4,5)]
partner={}
for a,b in pairs: partner[a]=b; partner[b]=a
def neighbors(d): return {partner[d],(d+1)%10,(d-1)%10}
seen={0:0}; queue=[0]
while queue:
    d=queue.pop(0)
    for n in neighbors(d):
        if n not in seen: seen[n]=seen[d]+1; queue.append(n)
print('distances from 0:',seen)
print('connected:', len(seen)==10)
# Lesson: the diagram as data — structure you can walk beats structure you admire.

